"""Search an Element in a Linked List — linear traversal.

Time: O(n)   Space: O(1)
"""
from typing import List


class _Node:
    __slots__ = ("val", "next")

    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt


class Solution:
    def search(self, values: List[int], key: int) -> int:
        head = None
        for value in reversed(values):
            head = _Node(value, head)

        position, node = 1, head
        while node:
            if node.val == key:
                return position
            node = node.next
            position += 1
        return -1
